# ---- helpers ------------------------------------------------------------------
def _eq(a, b, tag):
    assert a == b, "%s: %r != %r" % (tag, a, b)


def _bits(x):
    return (repr(x), math.copysign(1.0, x))


def _deep(a, b, tag):
    if isinstance(a, dict) and isinstance(b, dict):
        _eq(sorted(a.keys()), sorted(b.keys()), tag + ".keys")
        for k in a:
            _deep(a[k], b[k], tag + "." + str(k))
    elif isinstance(a, list) and isinstance(b, list):
        _eq(len(a), len(b), tag + ".len")
        for i, (x, y) in enumerate(zip(a, b)):
            _deep(x, y, "%s[%d]" % (tag, i))
    elif isinstance(a, float) or isinstance(b, float):
        _eq(_bits(a), _bits(b), tag + ".bits")
    else:
        _eq(a, b, tag)


def C(solve, mode, **kw):
    return solve(mode, **kw)


def _exc(fn):
    try:
        fn()
        return None
    except Exception as e:
        return {"type": type(e).__name__, "msg": str(e)}


def _flat(x):
    if isinstance(x, list):
        out = []
        for v in x:
            out.extend(_flat(v))
        return out
    return [x]


def label(v):
    return str(v).replace("-", "NEG").replace(".", "P").replace(" ", "_")


def WT(name):
    return globals()[name]


# ---- census / structure --------------------------------------------------------
def check_census_matches(solve):
    _deep(C(solve, "census"), CENSUS871, "census")


def check_census_fresh_dict(solve):
    a = C(solve, "census")
    b = C(solve, "census")
    assert a is not b, "census must be a fresh dict"
    assert a["top_level"] is not b["top_level"], "top_level must be fresh"
    assert a["funcs"] is not b["funcs"], "funcs must be fresh"
    a["top_level"].append([0, "MUTATED"])
    a["funcs"]["flanger"][0] = 0
    _eq(len(b["top_level"]), 30, "census.top_level.immutable")
    _eq(b["funcs"]["flanger"], [713, 868], "census.funcs.immutable")
    _deep(b, CENSUS871, "census.after_mutation")


def check_structural_lists(solve):
    c = C(solve, "census")
    _eq(c["modes"], MODES871, "census.modes")
    _eq(c["params"], PARAMS871, "census.params")
    _eq(c["defaults"], DEFAULTS871, "census.defaults")
    _eq(c["modulations"], MODULATIONS871, "census.modulations")
    _eq(c["interpolations"], INTERPOLATIONS871, "census.interpolations")
    _eq(c["wave_types"], WAVE_TYPES871, "census.wave_types")
    _eq(c["data_types"], DATA_TYPES871, "census.data_types")
    _eq(c["funcs"], FUNCS871, "census.funcs")
    _eq(len(MODES871), 8, "modes.len")
    _eq(len(PARAMS871), 9, "params.len")
    _eq(len(MODULATIONS871), 2, "modulations.len")
    _eq(len(INTERPOLATIONS871), 2, "interpolations.len")


def check_census_source(solve):
    c = C(solve, "census")
    _eq(c["source"], "pytorch/audio main::src/torchaudio/functional/filtering.py",
        "census.source")
    _eq(c["source_lines"], 1702, "census.source_lines")
    _eq(c["n_top_level"], 30, "census.n_top_level")
    _eq(c["top_level"][0], [12, "_dB2Linear"], "census.first")
    _eq(c["top_level"][-1], [1485, "vad"], "census.last")
    _eq(c["arg_names"], ["waveform", "sample_rate", "delay", "depth",
                         "regen", "width", "speed", "phase", "modulation",
                         "interpolation"], "census.arg_names")


def check_census_defaults(solve):
    _eq(DEFAULTS871, {"delay": 0.0, "depth": 2.0, "regen": 0.0,
                      "width": 71.0, "speed": 0.5, "phase": 25.0,
                      "modulation": "sinusoidal", "interpolation": "linear"},
        "defaults.literals")
    _eq(C(solve, "census")["defaults"], DEFAULTS871, "defaults.via_solve")


def check_all_modes_dispatch(solve):
    for m in MODES871:
        r = C(solve, m)
        assert isinstance(r, dict), "mode %s must return a dict" % m
        assert "type" not in r, "mode %s must not be an error dict" % m
    _eq(sorted(MODES871), sorted(["census", "wave_table", "flanger",
                                  "branches", "params", "prefix", "errors",
                                  "shapes"]), "modes.exact")


def check_unknown_mode(solve):
    _eq(_exc(lambda: C(solve, "no_such_mode")), EXC_UNKNOWN,
        "unknown_mode.exc")
    _eq(EXC_UNKNOWN["type"], "ValueError", "unknown_mode.type")
    assert "expected one of" in EXC_UNKNOWN["msg"], "unknown_mode.msg"


# ---- wave tables ---------------------------------------------------------------
def check_wave_table_default(solve):
    _deep(C(solve, "wave_table"), WT_SINE_FLOAT_N10, "wt.default")


def check_wave_table_fresh_lists(solve):
    a = C(solve, "wave_table")
    b = C(solve, "wave_table")
    assert a["values"] is not b["values"], "values must be fresh"
    a["values"].append(999.0)
    _eq(len(b["values"]), 10, "wt.values.immutable")
    _deep(b, WT_SINE_FLOAT_N10, "wt.fresh.after_mutation")


def check_wave_table_sine_float_small(solve):
    for n in (1, 2, 3, 4, 5, 8, 10, 16, 20, 32):
        got = C(solve, "wave_table", table_size=n, wave_type="SINE",
                data_type="FLOAT", min=1.0, max=2.0, wt_phase=3 * math.pi / 2)
        _deep(got, WT("WT_SINE_FLOAT_N%d" % n), "wt.sine.float.n%d" % n)


def check_wave_table_sine_float_large_n(solve):
    for n in (64, 98, 196):
        got = C(solve, "wave_table", table_size=n, wave_type="SINE",
                data_type="FLOAT", min=1.0, max=2.0, wt_phase=3 * math.pi / 2)
        _deep(got, WT("WT_SINE_FLOAT_N%d" % n), "wt.sine.large.n%d" % n)
        _eq(got["length"], n, "wt.sine.large.length")
        assert sorted(got["points"]) == list(range(n)), "points permutation"


def check_wave_table_triangle_float(solve):
    for n in (1, 2, 3, 4, 5, 8, 10, 16, 20, 32, 64, 98, 196):
        got = C(solve, "wave_table", table_size=n, wave_type="TRIANGLE",
                data_type="FLOAT", min=1.0, max=2.0, wt_phase=3 * math.pi / 2)
        _deep(got, WT("WT_TRI_FLOAT_N%d" % n), "wt.tri.float.n%d" % n)


def check_wave_table_sine_int(solve):
    for n in (4, 5, 8, 10, 16, 32, 98):
        got = C(solve, "wave_table", table_size=n, wave_type="SINE",
                data_type="INT", min=0.0, max=5.0, wt_phase=3 * math.pi / 2)
        _deep(got, WT("WT_SINE_INT_N%d" % n), "wt.sine.int.n%d" % n)
        _eq(got["dtype"], "torch.int32", "wt.sine.int.dtype")
        assert all(type(v) is int for v in got["values"]), "int values"


def check_wave_table_triangle_int(solve):
    for n in (4, 5, 8, 10, 16, 32, 98):
        got = C(solve, "wave_table", table_size=n, wave_type="TRIANGLE",
                data_type="INT", min=-3.0, max=5.0, wt_phase=3 * math.pi / 2)
        _deep(got, WT("WT_TRI_INT_N%d" % n), "wt.tri.int.n%d" % n)
        _eq(got["dtype"], "torch.int32", "wt.tri.int.dtype")


def check_wave_table_ranges(solve):
    ranges = {
        "NEG": (-3.0, 5.0), "NEGDELAY": (-2.0, 0.0),
        "FRAC": (7.5, 12.25), "UNIT": (0.0, 1.0),
    }
    for tag, (mn, mx) in ranges.items():
        for wt, prefix in (("SINE", "WT_SINE_"),
                           ("TRIANGLE", "WT_TRIANGLE_")):
            got = C(solve, "wave_table", table_size=10, wave_type=wt,
                    data_type="FLOAT", min=mn, max=mx,
                    wt_phase=3 * math.pi / 2)
            _deep(got, WT(prefix + tag), "wt.%s.%s" % (wt, tag))
            _eq(got["kwargs"]["min"], mn, "wt.range.min")
            _eq(got["kwargs"]["max"], mx, "wt.range.max")


def check_wave_table_phases(solve):
    phases = {
        "PH0": 0.0, "PHPI2": math.pi / 2, "PHPI": math.pi,
        "PH2PI": 2 * math.pi,
    }
    for tag, ph in phases.items():
        got = C(solve, "wave_table", table_size=10, wave_type="SINE",
                data_type="FLOAT", min=1.0, max=2.0, wt_phase=ph)
        _deep(got, WT("WT_" + tag), "wt.phase.%s" % tag)
        _eq(got["phase_offset"], int(ph / math.pi / 2 * 10 + 0.5),
            "wt.phase.offset.%s" % tag)


def check_wave_table_dtypes(solve):
    f = C(solve, "wave_table")
    i = C(solve, "wave_table", data_type="INT", min=0.0, max=5.0)
    _eq(f["dtype"], "torch.float32", "wt.float.dtype")
    _eq(i["dtype"], "torch.int32", "wt.int.dtype")
    _eq(f["length"], 10, "wt.float.length")
    _eq(i["length"], 10, "wt.int.length")
    assert all(type(v) is float for v in f["values"]), "float values"
    assert all(type(v) is int for v in i["values"]), "int values"


def check_wave_table_phase_offset_formula(solve):
    for n in (1, 2, 5, 10, 16, 98):
        for ph in (0.0, math.pi / 2, 3 * math.pi / 2, 2 * math.pi):
            r = C(solve, "wave_table", table_size=n, wt_phase=ph)
            _eq(r["phase_offset"], int(ph / math.pi / 2 * n + 0.5),
                "wt.offset.%d.%.3f" % (n, ph))
            _eq(sorted(r["points"]), list(range(n)), "wt.points.perm")
            _eq(r["points"], [(k + r["phase_offset"]) % n for k in range(n)],
                "wt.points.formula")


def check_wave_table_large_n_symmetry(solve):
    w = WT_SINE_FLOAT_N196["values"]
    _eq(len(w), 196, "wt.n196.len")
    for p in (0, 1, 49, 98):
        q = (p + 98) % 196
        assert abs(w[p] + w[q] - 3.0) < 1e-5, "sine symmetry at %d" % p


def check_wave_table_int_vs_float(solve):
    f = C(solve, "wave_table", data_type="FLOAT", min=-3.0, max=5.0)
    i = C(solve, "wave_table", data_type="INT", min=-3.0, max=5.0)
    assert f["values"] != i["values"], "INT branch must differ from FLOAT"
    _eq(f["dtype"], "torch.float32", "int_vs_float.f")
    _eq(i["dtype"], "torch.int32", "int_vs_float.i")


# ---- default flanger -----------------------------------------------------------
def check_flanger_default(solve):
    _deep(C(solve, "flanger"), FLANGER_DEFAULT, "flanger.default")


def check_flanger_out(solve):
    r = C(solve, "flanger")
    _deep(r["out"], FLANGER_OUT, "flanger.out")
    _eq(r["shape"], FLANGER_SHAPE, "flanger.shape")
    _eq(r["dtype"], "torch.float64", "flanger.dtype")


def check_flanger_derived(solve):
    _deep(C(solve, "flanger")["derived"], FLANGER_DERIVED,
          "flanger.derived")


def check_flanger_wave_table(solve):
    _deep(C(solve, "flanger")["wave_table"], FLANGER_WT, "flanger.wt")


def check_derived_algebra(solve):
    d = FLANGER_DERIVED
    _eq(d["feedback_gain"], 0.2, "derived.feedback_gain")
    _eq(d["channel_phase"], 0.25, "derived.channel_phase")
    _eq(d["delay_min"], 0.005, "derived.delay_min")
    _eq(d["delay_depth"], 0.01, "derived.delay_depth")
    assert abs(d["in_gain"] + 0.7 / 1.7 - 1.0) < 1e-15, "in_gain + raw == 1"
    assert abs(d["delay_gain"] - 0.7 / 1.7 * 0.8) < 1e-15, "delay_gain"
    _eq(d["delay_buf_length"] - 2.0, d["table_max"], "L-2 == table_max")
    _eq(d["channel_phases"], [0, 3], "derived.channel_phases")
    _eq(d["wave_type"], "SINE", "derived.wave_type")


def check_defaults_applied(solve):
    explicit = C(solve, "flanger", sample_rate=100, delay=5.0, depth=10.0,
                 regen=20.0, width=70.0, speed=10.0, phase=25.0,
                 modulation="sinusoidal", interpolation="linear")
    _deep(explicit, FLANGER_DEFAULT, "defaults.applied")


