def check_negative_delay_outputs(solve):
    cases = {
        "NEG_NEG_D20_D10": dict(delay=-20.0, depth=10.0),
        "NEG_NEG_D20_D0": dict(delay=-20.0, depth=0.0),
        "NEG_NEG_D5_D10": dict(delay=-5.0, depth=10.0),
        "NEG_NEG_D20_TRIQ": dict(delay=-20.0, depth=10.0,
                                 modulation="triangular",
                                 interpolation="quadratic"),
        "NEG_NEG_D20_SINQ": dict(delay=-20.0, depth=10.0,
                                 interpolation="quadratic"),
    }
    for name, kw in cases.items():
        _deep(C(solve, "flanger", **kw)["out"], WT(name), "neg." + name)


