                    key = "%s_%s_%s_%s" % (label(d), label(dp), label(rg),
                                           label(sp))
                    assert key in GRID871, "grid key " + key
                    _deep(C(solve, "flanger", delay=d, depth=dp, regen=rg,
                            speed=sp)["out"], GRID871[key], "grid." + key)


