            for i in ("linear", "quadratic"):
                key = "%s_%s_%s" % (tag, m[:3], i[:3])
                assert key in WAVE_GRID871, "wave grid key " + key
                _deep(C(solve, "flanger", waveform=w, modulation=m,
                        interpolation=i)["out"], WAVE_GRID871[key],
                      "wavegrid." + key)


