def check_params_mode_high_resolution(solve):
    # A short waveform leaves the delay ring unfilled, so delay=20 and 21
    # happen to produce identical output. A 60-sample waveform at sr=1000
    # fills the ring and makes the scan values observable.
    p = C(solve, "params", sample_rate=1000, waveform=WAVE_HIRES871)
    _deep(p["delay"][2][1], PARAMS_HIRES_DELAY_V2, "params.hires.delay_v2")
    f = C(solve, "flanger", delay=20.0, sample_rate=1000,
          waveform=WAVE_HIRES871)["out"]
    _deep(p["delay"][2][1], f, "params.hires.self_consistent")
